#!/usr/bin/env python3
"""data/particle-fx-catalog.json -> docs/particle-fx-catalog.md (human summary).

Per family: what the sprite is, how many emitters, behaviour mix, typical
params, and a sample of the per-emitter notes (all notes live in the JSON).
"""
import json, os, sys
from collections import Counter, defaultdict

HERE = os.path.dirname(os.path.abspath(__file__))
APP = os.path.abspath(os.path.join(HERE, "..", ".."))
CAT = os.path.join(APP, "data", "particle-fx-catalog.json")
OUT = sys.argv[1] if len(sys.argv) > 1 else os.path.join(APP, "docs", "particle-fx-catalog.md")
SAMPLE = 14

cat = json.load(open(CAT))
fam_of = defaultdict(list)
for did, e in cat["emitters"].items():
    fam_of[e["family"]].append((did, e))


def med(xs):
    xs = sorted(xs)
    return xs[len(xs) // 2] if xs else 0


lines = ["# Particle FX catalog (summary)", "",
         "Generated by `tools/particle-fx/catalog_doc.py` from `data/particle-fx-catalog.json` — the source of truth "
         "for `?particleFx` (see docs/url-flags.md and docs/HANDOFF-particle-fx-2026-10-09.md). Every one of the "
         f"{len(cat['emitters'])} retail ParticleEmitters has an entry with its own note and params; this page groups "
         "them by visual family and samples the notes. Param keys: gain/core (HDR + hot core), tint0→tint1 (colour over "
         "life), fadeIn/fadeOut, erode, flicker/twinkle/pulse, spin, wobble, soft (m), nearFade (m), lit.", ""]
lines.append("| family | emitters | what it is |")
lines.append("|---|---|---|")
for fam, items in sorted(fam_of.items(), key=lambda kv: -len(kv[1])):
    lines.append(f"| {fam} | {len(items)} | {cat['families'].get(fam, '')} |")
lines.append("")
for fam, items in sorted(fam_of.items(), key=lambda kv: -len(kv[1])):
    lines.append(f"## {fam} — {len(items)} emitters")
    lines.append("")
    lines.append(f"_{cat['families'].get(fam, '')}_")
    lines.append("")
    beh = Counter(e["behavior"] for _, e in items)
    lines.append("Behaviours: " + ", ".join(f"{b} {n}" for b, n in beh.most_common()))
    keys = ["gain", "core", "fadeIn", "fadeOut", "erode", "flicker", "twinkle", "spin", "soft", "nearFade", "lit", "pulse"]
    typ = []
    for k in keys:
        vals = [e["params"].get(k, 0) for _, e in items]
        nz = [v for v in vals if v]
        if nz:
            typ.append(f"{k} {med(nz):g} ({len(nz)}/{len(items)})")
    if typ:
        lines.append("")
        lines.append("Typical (median of non-neutral, count): " + "; ".join(typ))
    reviewed = sum(1 for _, e in items if e.get("reviewed"))
    lines.append("")
    lines.append(f"Reviewed: {reviewed}/{len(items)}")
    lines.append("")
    # sample: spread across behaviours, prefer notes naming weenies/effects
    picks, seen_beh = [], Counter()
    for did, e in sorted(items, key=lambda kv: (-len(kv[1]["note"]), kv[0])):
        if len(picks) >= SAMPLE:
            break
        if seen_beh[e["behavior"]] >= max(2, SAMPLE // max(1, len(beh))):
            continue
        seen_beh[e["behavior"]] += 1
        picks.append((did, e))
    for did, e in sorted(picks):
        lines.append(f"- `{did}` ({e['behavior']}) — {e['note']}")
    lines.append("")
lines.append("## Synthesized emitters")
lines.append("")
for name, s in cat["synthesized"].items():
    lines.append(f"- **{name}** ({s['family']}; {s['sprite']}) — {s['note']}")
lines.append("")
open(OUT, "w").write("\n".join(lines))
print("wrote", OUT, os.path.getsize(OUT), "bytes")
